mapper.select:
SELECT id, started_at, finished_at, sources, tables_scanned, columns_scanned,
            schema_truncated, cap, returned, accepted, dropped, tables_covered, error
       FROM mapping_exploration_runs
      WHERE kb_id = #{kbId}
      ORDER BY started_at DESC
      LIMIT #{limit}

mapper.update:
UPDATE concept_mappings
    SET status = #{status}, decided_by = #{actor}, decided_at = now(), updated_at = now()
  WHERE id = #{mappingId} AND kb_id = #{kbId}

mapper.insert:
INSERT INTO entity_types (id, kb_id, key, label, builtin, description)
 SELECT #{id}, #{kbId}, #{key}, #{label}, TRUE, #{description}
  WHERE NOT EXISTS (SELECT 1 FROM entity_types WHERE kb_id = #{kbId} AND key = #{key})

mapper.select:
SELECT m.id FROM concept_mappings m
 WHERE m.kb_id = #{kbId} AND m.status = 'confirmed'
   AND m.embedding IS NOT NULL AND m.embedded_model = #{model}

mapper.update:
UPDATE concept_mappings
   SET embedding = #{vector}::vector, embedded_model = #{model}, embedded_text = #{text}
 WHERE id = #{id}

mapper.select:
SELECT id FROM concept_mappings
 WHERE kb_id = #{kbId} AND status = 'confirmed' AND embedding IS NOT NULL
   AND embedded_model = #{model}
   AND vector_dims(embedding) = vector_dims(#{vector}::vector)
 ORDER BY embedding <=> #{vector}::vector
 LIMIT #{limit}

mapper.update:
UPDATE mapping_exploration_runs
   SET sources = #{sources,typeHandler=tech.seexun.jknow.store.typehandler.TextArrayTypeHandler}, tables_scanned = #{tables}, columns_scanned = #{columns},
       schema_truncated = #{truncated}, cap = #{cap}
 WHERE id = #{id}

UPDATE mapping_exploration_runs
   SET finished_at = now(), returned = #{returned}, accepted = #{accepted},
       dropped = #{dropped}, tables_covered = #{tablesCovered,typeHandler=tech.seexun.jknow.store.typehandler.TextArrayTypeHandler}
 WHERE id = #{id}
